// gftd vertex — ADR-0040 Vertex DID Tier inspector + Tier B sub-path DID
// minting CLI scaffold. Reads tier classification from `30-graph/deps.toml
// [vertex_tier.*]` (the SSoT generated by `pnpm tier:gen`).
//
// Subcommands (Phase 3 scaffold; emit/apply path is intentionally guarded):
//
//	gftd vertex tier <table>            — print A/B/C for a vertex_* table
//	gftd vertex list --tier B           — list all tables in a tier
//	gftd vertex stats                   — print A/B/C counts + total
//	gftd vertex emit --tier=B           — DRY-RUN: enumerate candidate rows
//	                                       for sub-path did:gftd minting (no
//	                                       writes). `--apply` is currently
//	                                       gated and returns an error until
//	                                       a pilot project is approved per
//	                                       ADR-0040 Phase 3 follow-up.
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

func runVertex(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: gftd vertex <tier|list|stats|emit> [flags]")
	}
	switch args[0] {
	case "tier":
		return runVertexTier(args[1:])
	case "list":
		return runVertexList(args[1:])
	case "stats":
		return runVertexStats(args[1:])
	case "emit":
		return runVertexEmit(args[1:])
	default:
		return fmt.Errorf("unknown vertex subcommand %q. Available: tier, list, stats, emit", args[0])
	}
}

// ── deps.toml [vertex_tier.*] loader ─────────────────────────────────────────

type vertexTierRegistry struct {
	A []string
	B []string
	C []string
	M map[string]string // table → "A"|"B"|"C"
}

var (
	vtSectionRe = regexp.MustCompile(`^\[vertex_tier\.tier_([abc])\]\s*$`)
	vtTableRe   = regexp.MustCompile(`^\s*"(vertex_[a-z0-9_]+)"\s*,?\s*$`)
)

func loadVertexTierRegistry(depsPath string) (*vertexTierRegistry, error) {
	f, err := os.Open(depsPath)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", depsPath, err)
	}
	defer f.Close()

	reg := &vertexTierRegistry{M: make(map[string]string)}
	currentTier := "" // "" | "A" | "B" | "C"
	inTablesArray := false

	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 64*1024), 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		trim := strings.TrimSpace(line)
		// Section header
		if m := vtSectionRe.FindStringSubmatch(trim); m != nil {
			currentTier = strings.ToUpper(m[1])
			inTablesArray = false
			continue
		}
		// Other section ⇒ leave vertex_tier
		if strings.HasPrefix(trim, "[") && !strings.HasPrefix(trim, "[vertex_tier.") {
			currentTier = ""
			inTablesArray = false
			continue
		}
		if currentTier == "" {
			continue
		}
		if strings.HasPrefix(trim, "tables") && strings.Contains(trim, "[") {
			inTablesArray = true
			continue
		}
		if inTablesArray && strings.HasPrefix(trim, "]") {
			inTablesArray = false
			continue
		}
		if !inTablesArray {
			continue
		}
		if m := vtTableRe.FindStringSubmatch(line); m != nil {
			name := m[1]
			reg.M[name] = currentTier
			switch currentTier {
			case "A":
				reg.A = append(reg.A, name)
			case "B":
				reg.B = append(reg.B, name)
			case "C":
				reg.C = append(reg.C, name)
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(reg.M) == 0 {
		return nil, fmt.Errorf("%s: no [vertex_tier.tier_*] entries parsed", depsPath)
	}
	return reg, nil
}

func resolveDepsToml(override string) (string, error) {
	if override != "" {
		abs, err := filepath.Abs(override)
		if err != nil {
			return "", err
		}
		return abs, nil
	}
	// Walk up from cwd looking for `30-graph/deps.toml` to support invocation
	// from any subdirectory.
	cwd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	dir := cwd
	for {
		candidate := filepath.Join(dir, "30-graph", "deps.toml")
		if _, err := os.Stat(candidate); err == nil {
			return candidate, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return "", fmt.Errorf("could not locate 30-graph/deps.toml from %s (use --deps to override)", cwd)
}

// ── subcommands ──────────────────────────────────────────────────────────────

func runVertexTier(args []string) error {
	fs := flag.NewFlagSet("vertex tier", flag.ContinueOnError)
	depsPath := fs.String("deps", "", "path to 30-graph/deps.toml (default: auto-discover)")
	asJSON := fs.Bool("json", false, "JSON output")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if fs.NArg() == 0 {
		return fmt.Errorf("usage: gftd vertex tier <table-name>")
	}
	deps, err := resolveDepsToml(*depsPath)
	if err != nil {
		return err
	}
	reg, err := loadVertexTierRegistry(deps)
	if err != nil {
		return err
	}
	name := fs.Arg(0)
	tier, ok := reg.M[name]
	if *asJSON {
		out := map[string]any{"table": name, "tier": tier, "classified": ok}
		return json.NewEncoder(os.Stdout).Encode(out)
	}
	if !ok {
		fmt.Fprintf(os.Stderr, "%s: not classified (default tier = C per ADR-0040)\n", name)
		os.Exit(1)
	}
	fmt.Printf("%s\t%s\n", name, tier)
	return nil
}

func runVertexList(args []string) error {
	fs := flag.NewFlagSet("vertex list", flag.ContinueOnError)
	tier := fs.String("tier", "", "filter by tier: A | B | C (required)")
	depsPath := fs.String("deps", "", "path to 30-graph/deps.toml")
	limit := fs.Int("limit", 0, "max rows (0 = no limit)")
	asJSON := fs.Bool("json", false, "JSON output")
	if err := fs.Parse(args); err != nil {
		return err
	}
	t := strings.ToUpper(*tier)
	if t != "A" && t != "B" && t != "C" {
		return fmt.Errorf("--tier must be A, B, or C")
	}
	deps, err := resolveDepsToml(*depsPath)
	if err != nil {
		return err
	}
	reg, err := loadVertexTierRegistry(deps)
	if err != nil {
		return err
	}
	var tables []string
	switch t {
	case "A":
		tables = reg.A
	case "B":
		tables = reg.B
	case "C":
		tables = reg.C
	}
	sort.Strings(tables)
	if *limit > 0 && len(tables) > *limit {
		tables = tables[:*limit]
	}
	if *asJSON {
		return json.NewEncoder(os.Stdout).Encode(map[string]any{
			"tier":   t,
			"count":  len(tables),
			"tables": tables,
		})
	}
	for _, n := range tables {
		fmt.Println(n)
	}
	return nil
}

func runVertexStats(args []string) error {
	fs := flag.NewFlagSet("vertex stats", flag.ContinueOnError)
	depsPath := fs.String("deps", "", "path to 30-graph/deps.toml")
	asJSON := fs.Bool("json", false, "JSON output")
	if err := fs.Parse(args); err != nil {
		return err
	}
	deps, err := resolveDepsToml(*depsPath)
	if err != nil {
		return err
	}
	reg, err := loadVertexTierRegistry(deps)
	if err != nil {
		return err
	}
	total := len(reg.A) + len(reg.B) + len(reg.C)
	if *asJSON {
		return json.NewEncoder(os.Stdout).Encode(map[string]any{
			"tier_a": len(reg.A),
			"tier_b": len(reg.B),
			"tier_c": len(reg.C),
			"total":  total,
			"adr":    "adr-0040-vertex-did-tier-policy",
		})
	}
	fmt.Printf("ADR-0040 Vertex DID Tier registry (%s)\n", deps)
	fmt.Printf("  Tier A (actor DID):       %4d\n", len(reg.A))
	fmt.Printf("  Tier B (sub-path did:gftd): %4d\n", len(reg.B))
	fmt.Printf("  Tier C (no DID):          %4d\n", len(reg.C))
	fmt.Printf("  Total:                    %4d\n", total)
	return nil
}

func runVertexEmit(args []string) error {
	fs := flag.NewFlagSet("vertex emit", flag.ContinueOnError)
	tier := fs.String("tier", "B", "tier to emit (currently only B is supported)")
	project := fs.String("project", "", "filter Tier B tables by project prefix (e.g. kuruma, ongakuka)")
	depsPath := fs.String("deps", "", "path to 30-graph/deps.toml")
	dryRun := fs.Bool("dry-run", true, "preview only — do not mint DIDs (default: true)")
	apply := fs.Bool("apply", false, "actually mint sub-path DIDs (gated; requires Phase 3 pilot)")
	asJSON := fs.Bool("json", false, "JSON output")
	if err := fs.Parse(args); err != nil {
		return err
	}
	t := strings.ToUpper(*tier)
	if t != "B" {
		return fmt.Errorf("only --tier=B is supported by `vertex emit` (Tier A uses `gftd authn signin` / `gftd cohort seed`; Tier C does not get a DID)")
	}
	deps, err := resolveDepsToml(*depsPath)
	if err != nil {
		return err
	}
	reg, err := loadVertexTierRegistry(deps)
	if err != nil {
		return err
	}
	candidates := reg.B
	if *project != "" {
		filtered := candidates[:0:0]
		prefix := "vertex_" + strings.ToLower(*project) + "_"
		for _, n := range reg.B {
			if strings.HasPrefix(n, prefix) || n == "vertex_"+strings.ToLower(*project) {
				filtered = append(filtered, n)
			}
		}
		candidates = filtered
	}
	sort.Strings(candidates)

	out := map[string]any{
		"tier":             t,
		"project":          *project,
		"candidate_tables": candidates,
		"candidate_count":  len(candidates),
		"dry_run":          *dryRun,
		"apply":            *apply,
	}

	if *apply {
		// Hard gate: the actual sub-path did:gftd minting path requires
		// (1) PDS commit-pipeline trigger that derives identity rows on
		//     Tier B INSERT, OR
		// (2) routing-gateway generic did:web path resolver (ADR-0023 §2),
		// neither of which is wired to production at the time of this scaffold.
		// A pilot project + companion ADR is required before flipping --apply.
		out["apply_gated"] = true
		out["next_step"] = "Phase 3 pilot — see ADR-0040 §Rollout"
		if *asJSON {
			_ = json.NewEncoder(os.Stdout).Encode(out)
		}
		return fmt.Errorf("--apply is gated until ADR-0040 Phase 3 pilot is approved (PDS INSERT trigger + routing-gateway path resolver)")
	}

	if *asJSON {
		return json.NewEncoder(os.Stdout).Encode(out)
	}

	fmt.Printf("ADR-0040 Tier %s emit DRY-RUN (%s)\n", t, deps)
	if *project != "" {
		fmt.Printf("  filter:  project = %q\n", *project)
	}
	fmt.Printf("  candidate vertex tables: %d\n", len(candidates))
	for _, n := range candidates {
		fmt.Printf("    %s\n", n)
	}
	fmt.Println()
	fmt.Println("To actually mint sub-path DIDs:")
	fmt.Println("  1. Approve a pilot project per ADR-0040 §Rollout (Phase 3)")
	fmt.Println("  2. Wire PDS commit-pipeline INSERT trigger for the Tier B labels")
	fmt.Println("  3. Generalize routing-gateway path-form did:web resolver (ADR-0023 §2)")
	fmt.Println("  4. Re-run with --apply (the gate will lift once the pilot ADR lands)")
	return nil
}
